using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace Resgrid.Model
{
	/// <summary>
	/// Every prompt of the dispatcher desk voice flow (plan D8), spoken through the TTS prompt pipeline
	/// (Web.Services ITwilioVoiceResponseService; pre-generated by the TTS static prompt refresh). English only, like the rest of the voice system's prompts.
	/// </summary>
	public static class DispatcherDeskVoicePrompts
	{
		// To the held caller.
		public const string HoldGreeting = "Thank you for calling. A dispatcher will be with you shortly. Please stay on the line.";
		public const string HoldContinue = "Please continue to hold. A dispatcher will be with you shortly.";
		public const string ConnectingCaller = "Connecting you to a dispatcher now.";
		public const string VoicemailIntro = "No dispatcher is available right now. After the tone, please leave your name, your location, a number to call you back and what you need, then press pound. If this is an emergency, hang up and call your local emergency number.";
		public const string VoicemailThanks = "Thank you. Your message has been passed to a dispatcher. Goodbye.";
		public const string VoicemailNotReceived = "We did not receive a message. Goodbye.";

		/// <summary>The recording could not be saved for the dispatchers: the caller must not hear that it was passed on.</summary>
		public const string VoicemailNotSaved = "Sorry, your message could not be passed to a dispatcher. Please call back. If this is an emergency, hang up and call your local emergency number. Goodbye.";
		public const string NoDispatcherAvailable = "No dispatcher is available right now. Please call back. If this is an emergency, hang up and call your local emergency number. Goodbye.";

		// To the dispatcher.
		public const string CallerGone = "The caller is no longer on the line. The call stays on your desk so you can call them back. Goodbye.";
		public const string NotWaitingForYou = "This call is no longer waiting for you. Goodbye.";
		public const string ReturnedToQueue = "The call has been returned to the queue. Goodbye.";
		public const string CallBackCancelled = "Call back cancelled. Goodbye.";
		public const string NoCallBackNumber = "There is no number to call back for this caller. Goodbye.";
		public const string UnknownCaller = "an unknown number";

		public static string DispatcherConnect(string caller) => $"Resgrid dispatch call from {caller}. Press 1 to connect.";

		public static string CallBack(string caller) => $"Resgrid dispatch call back to {caller}. Press 1 to call them now.";

		/// <summary>
		/// A phone number as the TTS voice should read it: digit by digit in groups ("5 5 5, 1 2 3, 4 5 6 7"), since a voice reads
		/// "555" as "five hundred fifty five". North American numbers drop the leading country code.
		/// </summary>
		public static string SpokenNumber(string number)
		{
			var digits = new string((number ?? string.Empty).Where(char.IsDigit).ToArray());

			if (digits.Length == 11 && digits[0] == '1')
				digits = digits.Substring(1);

			if (digits.Length == 0)
				return UnknownCaller;

			var groups = new List<string>();
			if (digits.Length == 10)
			{
				groups.Add(digits.Substring(0, 3));
				groups.Add(digits.Substring(3, 3));
				groups.Add(digits.Substring(6));
			}
			else
			{
				var i = 0;
				while (i < digits.Length)
				{
					// The last group takes four digits rather than leaving one on its own.
					var remaining = digits.Length - i;
					var take = remaining == 4 ? 4 : System.Math.Min(3, remaining);
					groups.Add(digits.Substring(i, take));
					i += take;
				}
			}

			var spoken = new StringBuilder();
			foreach (var group in groups)
			{
				if (spoken.Length > 0)
					spoken.Append(", ");

				spoken.Append(string.Join(" ", group.ToCharArray()));
			}

			return spoken.ToString();
		}

		/// <summary>The caller as the dispatcher hears it: their name when the desk has one, otherwise their number.</summary>
		public static string CallerFor(string sourceName, string sourceAddress)
		{
			return !string.IsNullOrWhiteSpace(sourceName) ? sourceName.Trim() : SpokenNumber(sourceAddress);
		}

		/// <summary>The prompts that never change, for TTS pre-generation.</summary>
		public static IReadOnlyCollection<string> GetStaticPrompts()
		{
			return new[]
			{
				HoldGreeting,
				HoldContinue,
				ConnectingCaller,
				VoicemailIntro,
				VoicemailThanks,
				VoicemailNotReceived,
				VoicemailNotSaved,
				NoDispatcherAvailable,
				CallerGone,
				NotWaitingForYou,
				ReturnedToQueue,
				CallBackCancelled,
				NoCallBackNumber
			};
		}
	}
}
